From 6d1bc6558ee6e65996ca5a0ce2a6e6ddc1772fc7 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 23:44:38 +0100
Subject: [PATCH] faces: Let an empty sensor label hide the sensor name

An empty sensor label was not saved and faces fell back to the sensor
name, so names like Total Usage could not be hidden. Save and honour
empty labels; typing the sensor's own name resets the label instead.

BUG: 501056
---
 faces/ConfigSensors.qml                       | 19 +++++++++++++------
 faces/SensorFaceController.cpp                |  5 +----
 .../contents/ui/FullRepresentation.qml        |  6 +++---
 .../piechart/contents/ui/UsedTotalDisplay.qml |  4 ++--
 .../contents/ui/CompactRepresentation.qml     |  4 ++--
 .../textonly/contents/ui/GroupedText.qml      |  4 ++--
 faces/import/Choices.qml                      | 19 +++++++------------
 faces/import/ExtendedLegend.qml               |  4 ++--
 8 files changed, 32 insertions(+), 33 deletions(-)

diff --git a/faces/ConfigSensors.qml b/faces/ConfigSensors.qml
index 86c0c6ba..6a3e8680 100644
--- a/faces/ConfigSensors.qml
+++ b/faces/ConfigSensors.qml
@@ -61,6 +61,16 @@ ColumnLayout {
         controller.sensorLabels = cfg_sensorLabels;
     }

+    function setSensorLabel(sensorId, label) {
+        let labels = Object.assign({}, cfg_sensorLabels);
+        if (label === undefined) {
+            delete labels[sensorId];
+        } else {
+            labels[sensorId] = label;
+        }
+        cfg_sensorLabels = labels;
+    }
+
     function loadConfig() {
         if (!arrayCompare(cfg_totalSensors, controller.totalSensors)) {
             cfg_totalSensors = controller.totalSensors;
@@ -141,8 +151,7 @@ ColumnLayout {

         onSelectedChanged: root.cfg_totalSensors = selected
         onSensorLabelChanged: (sensorId, label) => {
-            cfg_sensorLabels[sensorId] = label
-            root.cfg_sensorLabelsChanged()
+            root.setSensorLabel(sensorId, label)
         }
     }

@@ -167,8 +176,7 @@ ColumnLayout {
             root.cfg_sensorColorsChanged();
         }
         onSensorLabelChanged: (sensorId, label) => {
-            cfg_sensorLabels[sensorId] = label
-            root.cfg_sensorLabelsChanged()
+            root.setSensorLabel(sensorId, label)
         }
     }

@@ -185,8 +193,7 @@ ColumnLayout {

         onSelectedChanged: root.cfg_lowPrioritySensorIds = selected
         onSensorLabelChanged: (sensorId, label) => {
-            cfg_sensorLabels[sensorId] = label
-            root.cfg_sensorLabelsChanged()
+            root.setSensorLabel(sensorId, label)
         }
     }

diff --git a/faces/SensorFaceController.cpp b/faces/SensorFaceController.cpp
index 89fbf8c4..c8f54057 100644
--- a/faces/SensorFaceController.cpp
+++ b/faces/SensorFaceController.cpp
@@ -609,10 +609,7 @@ void SensorFaceController::setSensorLabels(const QVariantMap &labels)
     d->labelsGroup = KConfigGroup(&d->configGroup, "SensorLabels");

     for (auto it = labels.cbegin(); it != labels.cend(); ++it) {
-        const auto label = it.value().toString();
-        if (!label.isEmpty()) {
-            d->labelsGroup.writeEntry(it.key(), label);
-        }
+        d->labelsGroup.writeEntry(it.key(), it.value().toString());
     }

     d->syncTimer->start();
diff --git a/faces/facepackages/horizontalbars/contents/ui/FullRepresentation.qml b/faces/facepackages/horizontalbars/contents/ui/FullRepresentation.qml
index e6243c7c..42e59137 100644
--- a/faces/facepackages/horizontalbars/contents/ui/FullRepresentation.qml
+++ b/faces/facepackages/horizontalbars/contents/ui/FullRepresentation.qml
@@ -62,8 +62,8 @@ Faces.SensorFace {
                     Layout.fillWidth: true
                     Layout.minimumHeight: isTextOnly ? 0 : implicitHeight

-                    name: root.controller.sensorLabels[sensor.sensorId] || sensor.name
-                    shortName: root.controller.sensorLabels[sensor.sensorId] || sensor.shortName
+                    name: root.controller.sensorLabels[sensor.sensorId] ?? sensor.name
+                    shortName: root.controller.sensorLabels[sensor.sensorId] ?? sensor.shortName
                     value: sensor.formattedValue
                     indicator: Item {}

@@ -88,7 +88,7 @@ Faces.SensorFace {
                 Layout.fillWidth: true
                 Layout.minimumHeight: implicitHeight

-                name: root.controller.sensorLabels[sensor.sensorId] || sensor.shortName
+                name: root.controller.sensorLabels[sensor.sensorId] ?? sensor.shortName
                 value: sensor.formattedValue
                 indicator: Item {}

diff --git a/faces/facepackages/piechart/contents/ui/UsedTotalDisplay.qml b/faces/facepackages/piechart/contents/ui/UsedTotalDisplay.qml
index 035ee81a..344bbeb5 100644
--- a/faces/facepackages/piechart/contents/ui/UsedTotalDisplay.qml
+++ b/faces/facepackages/piechart/contents/ui/UsedTotalDisplay.qml
@@ -49,7 +49,7 @@ Item {
             Layout.leftMargin: root.contentMargin
             Layout.rightMargin: root.contentMargin

-            text: chart.sensorsModel.sensorLabels[usedSensor] ||  (usedSensorObject.name + (usedSensorObject.shortName.length > 0 ? "\x9C" + usedSensorObject.shortName : ""))
+            text: chart.sensorsModel.sensorLabels[usedSensor] ?? (usedSensorObject.name + (usedSensorObject.shortName.length > 0 ? "\x9C" + usedSensorObject.shortName : ""))
             horizontalAlignment: Text.AlignHCenter
             font: Kirigami.Theme.smallFont
             opacity: 0.75
@@ -132,7 +132,7 @@ Item {
             Layout.leftMargin: root.contentMargin
             Layout.rightMargin: root.contentMargin

-            text: chart.sensorsModel.sensorLabels[totalSensor] || (totalSensorObject.name + (totalSensorObject.shortName.length > 0 ? "\x9C" + totalSensorObject.shortName : ""))
+            text: chart.sensorsModel.sensorLabels[totalSensor] ?? (totalSensorObject.name + (totalSensorObject.shortName.length > 0 ? "\x9C" + totalSensorObject.shortName : ""))
             horizontalAlignment: Text.AlignHCenter
             font: Kirigami.Theme.smallFont
             opacity: 0.75
diff --git a/faces/facepackages/textonly/contents/ui/CompactRepresentation.qml b/faces/facepackages/textonly/contents/ui/CompactRepresentation.qml
index 7810fb86..feb382a3 100644
--- a/faces/facepackages/textonly/contents/ui/CompactRepresentation.qml
+++ b/faces/facepackages/textonly/contents/ui/CompactRepresentation.qml
@@ -78,8 +78,8 @@ Faces.CompactSensorFace {
                 Layout.preferredWidth: root.horizontalFormFactor ? preferredWidth : minimumWidth
                 Layout.alignment: Qt.AlignLeft | Qt.AlignVCenter

-                name: root.controller.sensorLabels[modelData] || sensor.name
-                shortName: root.controller.sensorLabels[modelData] || sensor.shortName
+                name: root.controller.sensorLabels[modelData] ?? sensor.name
+                shortName: root.controller.sensorLabels[modelData] ?? sensor.shortName
                 value: sensor.formattedValue
                 color: lowPriority ? "transparent" : root.colorSource.map[modelData]

diff --git a/faces/facepackages/textonly/contents/ui/GroupedText.qml b/faces/facepackages/textonly/contents/ui/GroupedText.qml
index 730f73da..8c164fa4 100644
--- a/faces/facepackages/textonly/contents/ui/GroupedText.qml
+++ b/faces/facepackages/textonly/contents/ui/GroupedText.qml
@@ -93,8 +93,8 @@ ColumnLayout {
                 }

                 delegate: ChartsControls.LegendDelegate {
-                    name: root.sensorLabels[modelData.sensorId] || (root.showGroups ? modelData.shortName : modelData.name)
-                    shortName: root.sensorLabels[modelData.sensorId] || modelData.shortName
+                    name: root.sensorLabels[modelData.sensorId] ?? (root.showGroups ? modelData.shortName : modelData.name)
+                    shortName: root.sensorLabels[modelData.sensorId] ?? modelData.shortName
                     value: modelData.formattedValue
                     color: root.colorSource.map[modelData.sensorId]

diff --git a/faces/import/Choices.qml b/faces/import/Choices.qml
index 18988393..f177187a 100644
--- a/faces/import/Choices.qml
+++ b/faces/import/Choices.qml
@@ -28,7 +28,7 @@ Control {

     signal selectColor(string sensorId)
     signal colorForSensorGenerated(string sensorId, color color)
-    signal sensorLabelChanged(string sensorId, string label)
+    signal sensorLabelChanged(string sensorId, var label)

     onSelectedChanged: {
         if (!control.selected) {
@@ -214,12 +214,9 @@ Control {
                             Label {
                                 id: label
                                 Layout.fillWidth: true
-                                text: {
-                                    if (!control.labels || !control.labels[sensor.sensorId]) {
-                                        return sensor.name
-                                    }
-                                    return control.labels[sensor.sensorId]
-                                }
+                                readonly property bool cleared: control.labels?.[sensor.sensorId] === ""
+                                text: control.labels?.[sensor.sensorId] || sensor.name
+                                color: cleared ? Kirigami.Theme.disabledTextColor : Kirigami.Theme.textColor
                                 elide: Text.ElideRight

                                 HoverHandler { id: handler }
@@ -267,14 +264,12 @@ Control {
                                 TextField {
                                     id: textField
                                     Layout.fillWidth: true
-                                    text: label.text
+                                    text: label.cleared ? "" : label.text
+                                    placeholderText: sensor.name
                                     cursorPosition: 0
                                     focus: true
                                     onAccepted: {
-                                        if (text == sensor.name) {
-                                            text = ""
-                                        }
-                                        sensorLabelChanged(sensor.sensorId, text)
+                                        sensorLabelChanged(sensor.sensorId, text == sensor.name ? undefined : text)
                                         layout.state = ""
                                     }
                                 }
diff --git a/faces/import/ExtendedLegend.qml b/faces/import/ExtendedLegend.qml
index b81a1adb..58ac9e7e 100644
--- a/faces/import/ExtendedLegend.qml
+++ b/faces/import/ExtendedLegend.qml
@@ -100,8 +100,8 @@ ChartsControls.Legend {
     Repeater {
         id: sensorsRepeater
         delegate: ChartsControls.LegendDelegate {
-            name: legend.sourceModel.sensorLabels[sensor.sensorId] || sensor.name
-            shortName: legend.sourceModel.sensorLabels[sensor.sensorId] || sensor.shortName
+            name: legend.sourceModel.sensorLabels[sensor.sensorId] ?? sensor.name
+            shortName: legend.sourceModel.sensorLabels[sensor.sensorId] ?? sensor.shortName
             value: sensor.formattedValue || ""

             indicator: Item { }
